class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        words = set(wordDict)
        n = len(s)
        max_len = max(map(len, wordDict))
        dp = [False] * (n + 1)
        dp[0] = True
        for i in range(1, n + 1):
            for length in range(1, min(i, max_len) + 1):
                if dp[i - length] and s[i - length:i] in words:
                    dp[i] = True
                    break
        return dp[n]

